<style>*{box-sizing:border-box}body{margin:0;background:#f5faf8;color:#18332c;font:15px/1.5 Inter,ui-sans-serif,system-ui,sans-serif}.top{background:#073d31;color:#eafff7;text-align:center;padding:8px;font-size:12px}.wrap{width:min(720px,calc(100% - 32px));margin:auto}.head{background:#fff;border-bottom:1px solid #e6eeeb}.headin{height:70px;display:flex;align-items:center;justify-content:space-between}.brand{font-size:23px;font-weight:850;letter-spacing:-1px;color:#087f5b;text-decoration:none}.brand span{color:#18332c}a{color:#087f5b}.panel{margin:55px auto;background:#fff;border:1px solid #e6eeeb;border-radius:18px;padding:34px;box-shadow:0 16px 40px #153e3010}.success{width:58px;height:58px;display:grid;place-items:center;border-radius:50%;background:#e7f5ee;color:#087f5b;font-size:30px}.panel h1{font-size:30px;margin:18px 0 5px}.muted{color:#70817c}.number{margin:20px 0;padding:14px;border-radius:10px;background:#f5faf8;font-weight:750}.row{display:flex;justify-content:space-between;gap:16px;padding:11px 0;border-bottom:1px solid #edf2ef}.address{white-space:pre-line}.btn{display:inline-block;margin-top:20px;padding:12px 18px;border-radius:9px;background:#087f5b;color:#fff;text-decoration:none;font-weight:750}@media(max-width:600px){.panel{margin:28px auto;padding:23px}.panel h1{font-size:26px}}</style></head>
<body><div class="top">Your health essentials, delivered with care · Secure mobile OTP</div><header class="head"><div class="wrap headin"><a class="brand" href="{{ route('home') }}">medi<span>Serve</span></a><a href="{{ route('home') }}">Continue shopping</a></div></header><main class="wrap"><section class="panel"><div class="success">✓</div><h1>Order placed</h1><p class="muted">Thanks, {{ auth()->user()->first_name }}. Your order is confirmed and ready for the store to process.</p><div class="number">Order number: {{ $order->order_number }}</div><div class="row"><span>Order status</span><strong>Placed</strong></div><div class="row"><span>Payment</span><strong>{{ $order->payment_method === 'cashfree' ? 'Cashfree paid' : 'Cash on delivery' }} · ₹{{ number_format((float)$order->subtotal, 2) }}</strong></div><div class="row"><strong>Delivery address</strong></div><div class="address">{{ $order->delivery_address }}</div><h2 style="font-size:17px;margin:22px 0 5px">Items</h2>@foreach($order->items as $item)<div class="row"><span>{{ $item['name'] }} × {{ $item['quantity'] }}</span><strong>₹{{ number_format($item['price'] * $item['quantity'], 2) }}</strong></div>@endforeach<a class="btn" href="{{ route('home') }}">Continue shopping</a></section></main></body></html>
